mappings.INQUIRY.response:
status = 200 and body.status = "UNPAID" and $type(body.amount) = "string"
  ? {"outcome": "SUCCESS", "partnerRef": body.bill_no,
     "attributes": {"amount": body.amount, "dueDate": body.due_date, "billPeriod": body.bill_period}}
: status = 200 and body.status = "VALID"
  ? {"outcome": "FAILED", "code": "E102", "message": "Bill already paid"}
: (status = 422 or status = 404) and $type(body.error_code) = "string" and body.error_code != ""
  ? {"outcome": "FAILED", "code": body.error_code, "message": body.error_message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.PAY.response:
status = 200 or status = 202
  ? (body.status = "VALID" and $type(body.val_id) = "string" and body.val_id != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.val_id}
    : body.status = "PENDING"
      ? {"outcome": "PENDING", "partnerRef": body.val_id}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.error_code) = "string" and body.error_code != ""
  ? {"outcome": "FAILED", "code": body.error_code, "message": body.error_message}
: status = 400
  ? {"outcome": "FAILED", "code": "HTTP_400"}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.STATUS_QUERY.response:
status = 200
  ? (body.status = "VALID" and $type(body.val_id) = "string" and body.val_id != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.val_id}
    : body.status = "PENDING"
      ? {"outcome": "PENDING", "partnerRef": body.val_id}
    : body.status = "FAILED" and $type(body.error_code) = "string"
      ? {"outcome": "FAILED", "code": body.error_code, "message": body.error_message}
    : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: status = 404 and body.status = "NOT_FOUND"
  ? {"outcome": "NOT_FOUND", "code": body.error_code}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.REVERSE.response:
status = 200
  ? (body.status = "REFUNDED" and $type(body.refund_ref_id) = "string" and body.refund_ref_id != ""
      ? {"outcome": "SUCCESS", "partnerRef": body.refund_ref_id}
      : {"outcome": "UNKNOWN", "reason": "MALFORMED_REPLY"})
: (status = 422 or status = 404) and $type(body.error_code) = "string" and body.error_code != ""
  ? {"outcome": "FAILED", "code": body.error_code, "message": body.error_message}
: {"outcome": "UNKNOWN", "reason": "UNEXPECTED_STATUS"}

mappings.CALLBACK.response:
$type(body.tran_id) != "string" or body.tran_id = "" ? {}
: body.status = "VALID" and $type(body.val_id) = "string" and body.val_id != ""
  ? {"outcome": "SUCCESS", "partnerRef": body.val_id, "reference": body.tran_id}
: body.status = "FAILED" and $type(body.error_code) = "string" and body.error_code != ""
  ? {"outcome": "FAILED", "partnerRef": body.val_id, "reference": body.tran_id,
     "code": body.error_code, "message": body.error_message}
: {}
